package com.simpletoob.app;
import android.app.AlertDialog;
import android.content.*;
import android.os.Bundle;
import android.widget.*;
import org.json.JSONArray;
import java.net.URI;
import java.net.URLDecoder;
import java.util.*;
public final class PlaylistsActivity extends BaseActivity {
    private LinearLayout root,body;private String local="",remote="",next="",title="Playlists";private List<Video> videos=new ArrayList<>();private LibraryStore library;private int generation;
    @Override public void onCreate(Bundle b){super.onCreate(b);library=app.library;root=ui.column();ui.root(root);root.addView(ui.toolbar("Playlists",this::finish));body=ui.column();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));String link=getIntent().getStringExtra("url");if(link!=null)openRemote(link,false);else list();}
    @Override protected void onImportsChanged(){if(body==null||!remote.isEmpty())return;if(local.isEmpty())list();else openLocal(local,title);}
    @Override protected void onResume(){super.onResume();if(body!=null&&remote.isEmpty()){if(local.isEmpty())list();else openLocal(local,title);}}
    private void list(){int token=++generation;local="";remote="";body.removeAllViews();LinearLayout actions=ui.column();ui.padded(actions);actions.addView(ui.chip("library","Create playlist",this::createPlaylist));ui.space(actions,12);actions.addView(ui.item("link","Open playlist link","Browse a public YouTube playlist",()->name("Playlist URL",u->openRemote(u,false))));actions.addView(ui.item("refresh","Import YouTube playlists",app.imports.status(),()->{if(app.sessions.present())app.imports.start(false,true,null);else WebSessionActivity.signIn(this);}));actions.addView(ui.item("settings","Import & schedule","Automatic refresh and import behavior",()->startActivity(new Intent(this,ImportSettingsActivity.class))));ui.divider(actions);actions.addView(ui.note("On this device · hold a playlist to edit"));body.addView(actions);List<LibraryStore.LocalPlaylist> entries=new ArrayList<>();ListView list=new ListView(this);list.setDivider(null);BaseAdapter adapter=new BaseAdapter(){public int getCount(){return entries.size();}public Object getItem(int p){return entries.get(p);}public long getItemId(int p){return p;}public android.view.View getView(int p,android.view.View old,android.view.ViewGroup parent){TextView text=old instanceof TextView?(TextView)old:ui.text("",15,ui.text);LibraryStore.LocalPlaylist row=entries.get(p);text.setPadding(ui.dp(20),ui.dp(14),ui.dp(20),ui.dp(14));text.setText(row.name+"\n"+row.size+" videos"+(row.remote.isEmpty()?" · local":" · YouTube"+(row.edited?" · local edits kept":"")));return text;}};list.setAdapter(adapter);list.setOnItemClickListener((parent,v,i,id)->openLocal(entries.get(i).id,entries.get(i).name));list.setOnItemLongClickListener((parent,v,i,id)->{edit(entries.get(i));return true;});body.addView(list,new LinearLayout.LayoutParams(-1,0,1));work(app.disk,library::playlists,result->{if(token!=generation)return;entries.addAll(result);adapter.notifyDataSetChanged();if(result.isEmpty())actions.addView(ui.note("No playlists yet. Create one or import from YouTube."));},this::error);}
    private void edit(LibraryStore.LocalPlaylist p){new AlertDialog.Builder(this).setTitle(p.name).setItems(p.remote.isEmpty()?new String[]{"Rename","Delete"}:new String[]{"Rename","Delete","Allow refresh from YouTube"},(d,i)->{if(i==0)name("New name",n->work(app.disk,()->{library.renamePlaylist(p.id,n);return true;},r->list(),this::error));else if(i==2)new AlertDialog.Builder(this).setTitle("Replace local edits on the next import?").setMessage("YouTube's version will replace the edited local copy when it next imports.").setNegativeButton("Cancel",null).setPositiveButton("Allow refresh",(x,j)->work(app.disk,()->{library.allowRemoteRefresh(p.id);return true;},r->list(),this::error)).show();else new AlertDialog.Builder(this).setTitle("Delete this local playlist?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,j)->work(app.disk,()->{library.deletePlaylist(p.id);return true;},r->list(),this::error)).show();}).show();}
    private void openLocal(String id,String name){int token=++generation;local=id;remote="";title=name;work(app.disk,()->library.playlistVideos(id),rows->{if(token!=generation)return;videos=rows;render();},this::error);}
    public static String playlistUrl(String input){try{URI u=URI.create(input);String h=u.getHost();if(!WebJson.youtube(input)||h==null||u.getRawQuery()==null)return null;for(String p:u.getRawQuery().split("&")){String[] v=p.split("=",2);if(v.length==2&&v[0].equals("list")){String id=URLDecoder.decode(v[1],"UTF-8");if(YoutubeWebClient.validPlaylist(id))return "https://www.youtube.com/playlist?list="+id;}}}catch(Exception ignored){}return null;}
    private void openRemote(String link,boolean more){String url=playlistUrl(link);if(url==null){error("Enter a valid YouTube playlist URL.");return;}remote=url;local="";String page=more?next:"";int token=++generation;work(app.sessions.present()?app.account:app.network,()->app.sessions.present()?app.web.playlist(url.substring(url.indexOf("list=")+5),page):app.youtube.playlist(url,page),result->{if(token!=generation)return;if(!more)videos=new ArrayList<>();videos.addAll(result.page.videos);next=result.page.next;if(!more)title=result.title;render();},this::error);}
    private void render(){body.removeAllViews();LinearLayout head=ui.column();ui.padded(head);head.addView(ui.heading(title,24));LinearLayout buttons=ui.row();ui.addChip(buttons,ui.quiet("‹ Playlists",this::list));ui.addChip(buttons,ui.chip("play","Play queue",()->{if(!videos.isEmpty())play(0);}));if(!remote.isEmpty())ui.addChip(buttons,ui.icon("save","Save loaded videos to a local playlist",()->name("Local playlist name",n->{List<Video> snapshot=new ArrayList<>(videos);work(app.disk,()->{String id=library.createPlaylist(n);for(Video v:snapshot)library.addToPlaylist(id,v);return id;},id->toast("Loaded videos copied locally"),this::error);})));head.addView(buttons);body.addView(head);ListView list=new ListView(this);List<String> labels=new ArrayList<>();for(Video v:videos)labels.add(v.title+"\n"+v.channel);list.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels));list.setOnItemClickListener((p,v,i,id)->play(i));list.setOnItemLongClickListener((p,v,i,id)->{if(local.isEmpty())return false;Video item=videos.get(i);String selectedList=local,selectedTitle=title;new AlertDialog.Builder(this).setTitle(item.title).setItems(new String[]{"Move up","Move down","Remove"},(d,j)->work(app.disk,()->{if(j==2)library.removeFromPlaylist(selectedList,item.id);else library.movePlaylistItem(selectedList,item.id,j==0?-1:1);return true;},r->{if(local.equals(selectedList))openLocal(selectedList,selectedTitle);},this::error)).show();return true;});body.addView(list,new LinearLayout.LayoutParams(-1,0,1));if(!remote.isEmpty()&&!next.isEmpty())body.addView(ui.button("Load more",false,()->openRemote(remote,true)));}
    private void play(int index){if(!local.isEmpty()){startActivity(new Intent(this,PlayerActivity.class).putExtra("video",videos.get(index).json().toString()).putExtra("local_playlist",local));return;}JSONArray queue=new JSONArray();for(int n=Math.max(0,index-100);n<Math.min(videos.size(),index+400);n++)queue.put(videos.get(n).id);startActivity(new Intent(this,PlayerActivity.class).putExtra("video",videos.get(index).json().toString()).putExtra("queue",queue.toString()));}
    private void createPlaylist(){if(!app.sessions.present()){name("Playlist name",n->work(app.disk,()->library.createPlaylist(n),id->list(),this::error));return;}new AlertDialog.Builder(this).setTitle("Create playlist").setItems(new String[]{"On this device","On YouTube"},(d,i)->name("Playlist name",n->{if(i==0)work(app.disk,()->library.createPlaylist(n),id->list(),this::error);else{String profile=app.sessions.profile(),revision=app.sessions.revision();work(app.account,()->new YoutubeWebClient(app.sessions,app.prefs).pin(profile,revision).createPlaylist(n),entry->{toast("YouTube playlist created");if(profile.equals(app.sessions.profile())&&revision.equals(app.sessions.revision()))app.imports.start(false,true,null);},this::error);}})).show();}
    private void name(String title,java.util.function.Consumer<String> callback){EditText e=ui.input(title);AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("Cancel",null).setPositiveButton("Continue",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String value=e.getText().toString().trim();if(value.isEmpty()){e.setError("Enter a value");return;}d.dismiss();callback.accept(value);}));d.show();}
}
